CREATE TABLE workflow_calendars(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,name TEXT NOT NULL,timezone TEXT NOT NULL,weekly_json TEXT NOT NULL,holidays TEXT NOT NULL DEFAULT 'none',closures_json TEXT NOT NULL DEFAULT '[]',active INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL,PRIMARY KEY(project_id,id));
CREATE TABLE sla_policies(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,name TEXT NOT NULL,calendar_id TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,conditions_json TEXT NOT NULL DEFAULT '{}',first_response_minutes REAL,next_response_minutes REAL,resolution_minutes REAL,pause_on_hold INTEGER NOT NULL DEFAULT 1,approaching_minutes REAL NOT NULL DEFAULT 15,unattended_minutes REAL,backup_user_ids_json TEXT NOT NULL DEFAULT '[]',active INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id,calendar_id) REFERENCES workflow_calendars(project_id,id));
CREATE INDEX sla_policy_order ON sla_policies(project_id,active,position,id);
CREATE TABLE ticket_sla_state(project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,policy_id TEXT NOT NULL,policy_json TEXT NOT NULL,calendar_json TEXT NOT NULL,last_event_id INTEGER NOT NULL DEFAULT 0,state_json TEXT NOT NULL,next_check_at INTEGER,updated_at INTEGER NOT NULL,PRIMARY KEY(project_id,conversation_id));
CREATE INDEX ticket_sla_state_due ON ticket_sla_state(next_check_at) WHERE next_check_at IS NOT NULL;
CREATE TABLE sla_alerts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,policy_id TEXT NOT NULL,metric TEXT NOT NULL,cycle INTEGER NOT NULL,kind TEXT NOT NULL,recipient_id TEXT,state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','acknowledged','resolved')),created_at INTEGER NOT NULL,acknowledged_at INTEGER,acknowledged_by TEXT,resolved_at INTEGER,notification_state TEXT NOT NULL DEFAULT 'pending' CHECK(notification_state IN ('pending','sending','complete','uncertain','failed','not_delivered')),notification_started_at INTEGER,notification_attempts INTEGER NOT NULL DEFAULT 0,notification_next_attempt_at INTEGER,notification_error TEXT,UNIQUE(project_id,conversation_id,policy_id,metric,cycle,kind,recipient_id));
CREATE INDEX sla_alert_open ON sla_alerts(project_id,state,created_at);
CREATE TABLE sla_scheduler_cursors(id TEXT PRIMARY KEY,after_id TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TRIGGER workflow_sla_alert_audit AFTER INSERT ON sla_alerts BEGIN
 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json) VALUES(lower(hex(randomblob(16))),NEW.project_id,NEW.created_at,'data','workflow.sla.'||NEW.kind,'succeeded','system','sla','system','conversation',NEW.conversation_id,json_object('alert_id',NEW.id,'metric',NEW.metric,'cycle',NEW.cycle,'policy_id',NEW.policy_id));
END;
CREATE TRIGGER workflow_sla_alert_state_audit AFTER UPDATE OF state ON sla_alerts WHEN OLD.state<>NEW.state BEGIN
 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json) VALUES(lower(hex(randomblob(16))),NEW.project_id,coalesce(NEW.resolved_at,NEW.acknowledged_at,NEW.created_at),'data','workflow.sla.'||NEW.state,'succeeded','system','sla','system','conversation',NEW.conversation_id,json_object('alert_id',NEW.id));
END;
